using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using StutterFix;
if(args.Length!=1)throw new ArgumentException("CacheCheck <new fixture directory>");
string root=Path.GetFullPath(args[0]);if(Directory.Exists(root))throw new Exception("Use a fresh directory; no existing data deleted");Directory.CreateDirectory(root);
int tests=0;
void Check(bool b,string what){tests++;if(!b)throw new Exception(what);}
string src=Path.Combine(root,"source.txt");File.WriteAllText(src,"data");string key=PersistentBlobCache.Key(src,"codec-v1/2048");
var cache=new PersistentBlobCache(Path.Combine(root,"cache"),1024);
byte[] data=Enumerable.Range(0,400).Select(i=>(byte)i).ToArray();
Check(cache.Write(key,data),"Write");Check(cache.TryRead(key,out var read)&&data.SequenceEqual(read),"SHA checked roundtrip");
Check(!cache.TryRead("../unsafe",out _)&&!cache.Write("../unsafe",data),"Path isolation");
Check(key!=PersistentBlobCache.Key(src,"codec-v2/2048")&&key!=PersistentBlobCache.Key(src,"codec-v1/1024"),"Codec and scale invalidation");
File.WriteAllText(src,"other");string changed=PersistentBlobCache.Key(src,"codec-v1/2048");Check(key!=changed&&!cache.TryRead(changed,out _),"Source size invalidation");
File.SetLastWriteTimeUtc(src,DateTime.UtcNow.AddHours(-2));Check(changed!=PersistentBlobCache.Key(src,"codec-v1/2048"),"Source time invalidation");
string path=Path.Combine(root,"cache",key+".sfc");byte[] damaged=File.ReadAllBytes(path);damaged[damaged.Length-1]^=1;File.WriteAllBytes(path,damaged);Check(!cache.TryRead(key,out _),"Corruption fallback");
Check(cache.Write(key,data)&&cache.TryRead(key,out read)&&read.SequenceEqual(data),"Atomic repair");
File.WriteAllBytes(path,new byte[]{1,2,3});Check(!cache.TryRead(key,out _),"Truncation fallback");Check(cache.Write(key,data),"Repair truncation");
string k2=PersistentBlobCache.Key(src,"two"),k3=PersistentBlobCache.Key(src,"three");Check(cache.Write(k2,data),"Second entry");File.SetLastWriteTimeUtc(Path.Combine(root,"cache",k2+".sfc"),DateTime.UtcNow.AddHours(-3));Check(cache.TryRead(key,out _),"Touch LRU");Check(cache.Write(k3,data)&&!cache.TryRead(k2,out _),"Least recently used evicted");Check(new DirectoryInfo(Path.Combine(root,"cache")).GetFiles().Sum(f=>f.Length)<=1024,"Quota");
Check(!cache.Write(k2,new byte[2048]),"Oversize rejected");
var invalid=new PersistentBlobCache(src,1024);Check(!invalid.Write(k2,data)&&!invalid.TryRead(k2,out _),"Unavailable directory fallback");
var original=new Dictionary<string,object>{{"tag","\ud800\0한글"},{"floor",123},{"value",-0.0f},{"array",new List<object>{true,false,null,"x"}}};
var snapshot=(Dictionary<string,object>)JsonSnapshot.Decode(JsonSnapshot.Encode(original));Check(original.Keys.SequenceEqual(snapshot.Keys),"DOM key order");Check((string)snapshot["tag"]==(string)original["tag"],"Exact UTF16 including lone surrogate");Check(BitConverter.SingleToInt32Bits((float)snapshot["value"])==BitConverter.SingleToInt32Bits((float)original["value"]),"Float bit pattern");
bool bad=false;try{JsonSnapshot.Decode(new byte[]{7,255,255,255,127});}catch(InvalidDataException){bad=true;}Check(bad,"Untrusted count rejected");
Check(JsonSnapshot.Fingerprint("\ud800")!=JsonSnapshot.Fingerprint("\ufffd"),"Fingerprint preserves UTF16");
var concurrent=new PersistentBlobCache(Path.Combine(root,"parallel"),4096);Parallel.For(0,32,i=>{string k=PersistentBlobCache.Key(src,"entry-"+i);if(!concurrent.Write(k,data))throw new Exception("Concurrent write");if(concurrent.TryRead(k,out var v)&&!v.SequenceEqual(data))throw new Exception("Concurrent corruption");});Check(new DirectoryInfo(Path.Combine(root,"parallel")).GetFiles().Sum(f=>f.Length)<=4096,"Concurrent quota/atomic visibility");
Console.WriteLine($"Cache checks {tests}, errors 0; fixture preserved");
